DELETE FROM quiz_options WHERE question_id IN (SELECT q.id FROM quiz_questions q WHERE q.lesson_id IN (SELECT l.id FROM lessons l JOIN chapters ch ON ch.id = l.chapter_id WHERE ch.revision_id = UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001')));
DELETE FROM quiz_questions WHERE lesson_id IN (SELECT l.id FROM lessons l JOIN chapters ch ON ch.id = l.chapter_id WHERE ch.revision_id = UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'));
DELETE FROM lesson_cells WHERE lesson_id IN (SELECT l.id FROM lessons l JOIN chapters ch ON ch.id = l.chapter_id WHERE ch.revision_id = UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'));
DELETE FROM lessons WHERE chapter_id IN (SELECT ch.id FROM chapters ch WHERE ch.revision_id = UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'));
DELETE FROM chapters WHERE revision_id = UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001');

AS content ON DUPLICATE KEY UPDATE slug = content.slug;

AS content ON DUPLICATE KEY UPDATE title = content.title, summary = content.summary, difficulty = content.difficulty,
    estimated_minutes = content.estimated_minutes, lesson_count = content.lesson_count;






