    (UUID_TO_BIN('01a1e005-0000-7000-8000-100000000001'), 'sql-cte', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000000'), 'PUBLISHED', UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'), NULL, NULL, 0, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000')
INSERT INTO course_revisions (id, course_id, status, title, summary, difficulty, estimated_minutes, lesson_count, submitted_at, published_at, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-100000000001'), 'PUBLISHED', 'SQL 5: CTE và truy vấn đệ quy', 'Đặt tên cho từng bước của truy vấn bằng WITH.\n- CTE cơ bản và nhiều CTE nối tiếp\n- Giải bài toán báo cáo nhiều bước\n- WITH RECURSIVE sinh dãy số và dãy tháng\n- Duyệt cây danh mục và sơ đồ tổ chức nhiều cấp', 'MEDIUM', 129, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000')
INSERT INTO chapters (id, revision_id, title, position, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e005-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'), 'WITH cơ bản', 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'), 'Giải bài toán nhiều bước', 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-200000000001'), 'CTE đệ quy', 3, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lessons (id, chapter_id, lesson_key, slug, title, body, position, estimated_minutes, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000001'), 'cte-la-gi', 'CTE là gì', '## Đặt tên cho một bước tính toán\n\nCTE (Common Table Expression) là một truy vấn con được **đặt tên** ở đầu câu lệnh bằng `WITH`, rồi dùng như một bảng:\n\n```sql\nWITH order_totals AS (\n    SELECT order_id, SUM(quantity * unit_price) AS order_total\n    FROM order_items\n    GROUP BY order_id\n)\nSELECT order_id, order_total\nFROM order_totals\nWHERE order_total > 20000000\nORDER BY order_total DESC;\n```\n\nĐây chính là bảng dẫn xuất của chặng trước, nhưng được kéo lên đầu và có tên rõ nghĩa.\n\n## Vì sao dễ đọc hơn\n\n- Đọc **từ trên xuống** như các bước: trước hết tính tổng mỗi đơn, sau đó lọc.\n- Tên CTE giải thích ý nghĩa, thay cho bí danh `t` vô nghĩa.\n- Kiểm tra từng bước dễ dàng: chạy riêng phần trong ngoặc là thấy kết quả trung gian.\n\n## Cú pháp\n\n```\nWITH ten_cte AS (\n    SELECT ...\n)\nSELECT ... FROM ten_cte ...;\n```\n\nCTE chỉ tồn tại trong **một câu lệnh**. Câu lệnh kết thúc là nó biến mất, không tạo bảng nào trong database.\n\n## Thử ngay\n\nÔ dưới tính tổng tiền mỗi đơn bằng CTE rồi nối với khách. Thử chạy riêng phần trong ngoặc.', 1, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000002'), 'nhieu-cte', 'Nhiều CTE nối tiếp nhau', '## Bước sau dùng kết quả bước trước\n\nNhiều CTE cách nhau bằng dấu phẩy, chỉ viết `WITH` một lần. CTE sau được dùng CTE trước:\n\n```sql\nWITH delivered_items AS (\n    SELECT o.customer_id, oi.quantity * oi.unit_price AS amount\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n),\ncustomer_spend AS (\n    SELECT customer_id, SUM(amount) AS spent\n    FROM delivered_items\n    GROUP BY customer_id\n)\nSELECT c.name, s.spent\nFROM customer_spend s\nJOIN customers c ON c.id = s.customer_id\nORDER BY s.spent DESC;\n```\n\n## Dùng một CTE nhiều lần\n\nMột CTE có thể được tham chiếu nhiều lần trong truy vấn chính, thay vì lặp lại cùng một subquery:\n\n```sql\nWITH customer_spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spent\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.customer_id\n)\nSELECT customer_id, spent\nFROM customer_spend\nWHERE spent > (SELECT AVG(spent) FROM customer_spend);\n```\n\n## Mẹo đặt tên\n\nĐặt tên CTE theo **nội dung**, không theo kỹ thuật: `customer_spend`, `monthly_revenue` tốt hơn `cte1`, `temp`.\n\n## Thử ngay\n\nÔ dưới tìm khách chi tiêu trên mức trung bình. Thử thêm một CTE thứ ba để lấy tên khách.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000003'), 'cte-hay-subquery', 'CTE hay subquery', '## Cùng sức mạnh, khác cách trình bày\n\nMọi CTE không đệ quy đều viết lại được bằng subquery trong FROM, và ngược lại. PostgreSQL từ bản 12 thường tối ưu hai cách như nhau.\n\n## Khi nào chọn CTE\n\n- Truy vấn có **từ hai bước** trở lên.\n- Một kết quả trung gian được **dùng nhiều lần**.\n- Bạn muốn **kiểm tra từng bước** khi gỡ lỗi.\n- Cần **đệ quy**: chỉ CTE làm được (chương 3).\n\n## Khi nào subquery là đủ\n\n- Một giá trị so sánh đơn giản: `WHERE price > (SELECT AVG(price) FROM products)`.\n- Điều kiện EXISTS, IN ngắn gọn.\n\n## Gỡ lỗi CTE từng bước\n\nKhi kết quả cuối sai, đổi truy vấn chính thành `SELECT * FROM ten_cte` để xem từng bước trung gian. Lỗi thường lộ ra ở bước đầu tiên có số dòng bất ngờ.\n\n## Thử ngay\n\nÔ dưới có hai CTE. Đổi dòng SELECT cuối thành `SELECT * FROM paid_orders` để xem bước trung gian.', 3, 8, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000004'), 'phan-khuc-khach-hang', 'Phân khúc khách hàng theo chi tiêu', '## Bài toán\n\n> Xếp mỗi khách vào nhóm VIP (từ 30 triệu), Thân thiết (từ 5 triệu), Thường, dựa trên tổng giá trị đơn đã giao. Đếm số khách mỗi nhóm.\n\n## Chia bước\n\n1. Tổng chi tiêu của mỗi khách.\n2. Gắn nhãn phân khúc.\n3. Đếm theo nhãn.\n\n```sql\nWITH customer_spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spent\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.customer_id\n),\nsegmented AS (\n    SELECT customer_id, spent,\n           CASE\n               WHEN spent >= 30000000 THEN ''VIP''\n               WHEN spent >= 5000000 THEN ''Thân thiết''\n               ELSE ''Thường''\n           END AS segment\n    FROM customer_spend\n)\nSELECT segment, COUNT(*) AS customers, SUM(spent) AS total_spent\nFROM segmented\nGROUP BY segment\nORDER BY total_spent DESC;\n```\n\nKết quả: 2 khách VIP, 4 khách Thân thiết, 6 khách Thường.\n\n## Đừng quên khách chưa mua\n\n12 khách có đơn đã giao, còn 3 khách chưa mua không nằm trong `customer_spend`. Nếu cần nhóm "Chưa mua", bắt đầu từ bảng customers và LEFT JOIN customer_spend:\n\n```sql\nWITH customer_spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spent\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.customer_id\n)\nSELECT c.name, COALESCE(s.spent, 0) AS spent,\n       CASE WHEN s.spent IS NULL THEN ''Chưa mua'' ELSE ''Đã mua'' END AS status\nFROM customers c\nLEFT JOIN customer_spend s ON s.customer_id = c.id\nORDER BY spent DESC;\n```\n\n## Thử ngay\n\nÔ dưới là lời giải đầy đủ. Thử đổi ngưỡng VIP thành 20 triệu.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000005'), 'so-sanh-voi-thong-ke-nhom', 'So sánh từng dòng với thống kê của nhóm', '## Tính thống kê một lần, nối vào từng dòng\n\n> Mỗi nhân viên: lương, lương trung bình phòng, và chênh lệch.\n\n```sql\nWITH department_stats AS (\n    SELECT department, ROUND(AVG(salary)) AS avg_salary, MAX(salary) AS max_salary\n    FROM employees\n    GROUP BY department\n)\nSELECT e.name, e.department, e.salary,\n       s.avg_salary,\n       e.salary - s.avg_salary AS diff_from_avg,\n       e.salary = s.max_salary AS is_top_paid\nFROM employees e\nJOIN department_stats s ON s.department = e.department\nORDER BY e.department, e.salary DESC NULLS LAST;\n```\n\nSo với subquery tương quan ở chặng trước, cách này tính thống kê **một lần cho mỗi phòng** rồi nối vào, dễ mở rộng thêm nhiều chỉ số.\n\n## Top của mỗi nhóm\n\nCột `is_top_paid` đã cho biết ai lương cao nhất phòng. Lọc nó:\n\n```sql\nWITH department_stats AS (\n    SELECT department, MAX(salary) AS max_salary\n    FROM employees\n    GROUP BY department\n)\nSELECT e.department, e.name, e.salary\nFROM employees e\nJOIN department_stats s ON s.department = e.department AND e.salary = s.max_salary\nORDER BY e.department;\n```\n\nỞ chặng Window function, bạn sẽ có cách mạnh hơn để lấy top N mỗi nhóm.\n\n## Thử ngay\n\nÔ dưới so sánh giá mỗi sản phẩm với giá trung bình của danh mục.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000006'), 'with-recursive-co-ban', 'WITH RECURSIVE: sinh dãy số', '## Một CTE gọi lại chính nó\n\nCTE đệ quy gồm hai phần nối bằng `UNION ALL`:\n\n```sql\nWITH RECURSIVE numbers(n) AS (\n    SELECT 1\n    UNION ALL\n    SELECT n + 1 FROM numbers WHERE n < 10\n)\nSELECT n FROM numbers;\n```\n\n- **Phần gốc** (`SELECT 1`): chạy một lần, tạo dòng xuất phát.\n- **Phần đệ quy** (`SELECT n + 1 FROM numbers ...`): chạy lặp lại trên các dòng vừa sinh ở vòng trước.\n- Dừng khi phần đệ quy không sinh thêm dòng nào.\n\n## Theo dõi từng vòng\n\n1. Vòng 0: phần gốc sinh `1`.\n2. Vòng 1: từ `1` sinh `2`.\n3. ...\n4. Vòng 9: từ `9` sinh `10`.\n5. Vòng 10: từ `10`, điều kiện `n < 10` sai, không sinh gì. Dừng.\n\n## Luôn có điểm dừng\n\nQuên điều kiện `WHERE n < 10`, truy vấn chạy mãi. Trên SQL Judge, nó sẽ bị dừng sau giới hạn thời gian và nhận kết quả quá thời gian. Trong hệ thống thật, nó có thể ăn hết tài nguyên của database.\n\n## Sinh dãy ngày\n\n```sql\nWITH RECURSIVE days(d) AS (\n    SELECT DATE ''2025-12-01''\n    UNION ALL\n    SELECT d + 1 FROM days WHERE d < DATE ''2025-12-07''\n)\nSELECT d, TO_CHAR(d, ''Day'') AS weekday FROM days;\n```\n\n## Thử ngay\n\nÔ dưới sinh 10 số đầu tiên và bình phương của chúng. Thử sinh dãy số chẵn tới 20.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000007'), 'lich-du-thang', 'Dựng lịch đủ tháng cho báo cáo', '## Tháng không có dữ liệu bị mất\n\n```sql\nSELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n       SUM(oi.quantity * oi.unit_price) AS revenue\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.id\nWHERE o.status = ''DELIVERED''\nGROUP BY 1\nORDER BY 1;\n```\n\nChỉ có 10 dòng: tháng 11 và 12 không có đơn nào **đã giao** nên biến mất khỏi báo cáo. Biểu đồ vẽ từ kết quả này sẽ nối thẳng tháng 10 sang tháng sau như thể không có gì xảy ra.\n\n## Dựng khung tháng rồi LEFT JOIN\n\n```sql\nWITH RECURSIVE months(month) AS (\n    SELECT DATE ''2025-01-01''\n    UNION ALL\n    SELECT (month + INTERVAL ''1 month'')::date FROM months WHERE month < DATE ''2025-12-01''\n),\nmonthly_revenue AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT m.month, COALESCE(r.revenue, 0) AS revenue\nFROM months m\nLEFT JOIN monthly_revenue r ON r.month = m.month\nORDER BY m.month;\n```\n\nĐủ 12 tháng, tháng 11 và 12 hiện doanh thu 0.\n\n## Mẫu dùng lại được\n\nKhung thời gian bằng CTE đệ quy, cộng LEFT JOIN số liệu, cộng COALESCE là mẫu chuẩn cho mọi báo cáo theo ngày, tuần, tháng. PostgreSQL còn có hàm `generate_series` làm việc này gọn hơn, nhưng CTE đệ quy chạy được trên hầu hết database.\n\n## Thử ngay\n\nÔ dưới là báo cáo đủ 12 tháng. Thử đổi sang đếm số đơn mọi trạng thái theo tháng.', 2, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000008'), 'duyet-cay-danh-muc', 'Duyệt cây danh mục', '## Dữ liệu dạng cây\n\n`categories.parent_id` tạo một cây: Điện tử chứa Máy tính, Máy tính chứa Laptop. SELF JOIN chỉ đi được một cấp, còn cây có thể sâu bao nhiêu cũng được.\n\n## Từ gốc đi xuống\n\n```sql\nWITH RECURSIVE tree AS (\n    SELECT id, name, parent_id, 1 AS depth, name::text AS path\n    FROM categories\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT c.id, c.name, c.parent_id, t.depth + 1, t.path || '' > '' || c.name\n    FROM categories c\n    JOIN tree t ON c.parent_id = t.id\n)\nSELECT path, depth\nFROM tree\nORDER BY path;\n```\n\n- Phần gốc: các danh mục không có cha (Điện tử, Thời trang, Sách).\n- Phần đệ quy: tìm các con của những dòng vừa sinh, tăng `depth` và nối thêm tên vào `path`.\n\nKết quả có cả đường dẫn đầy đủ như "Điện tử > Máy tính > Laptop" với độ sâu 3.\n\n## Mọi sản phẩm thuộc một nhánh\n\nChặng Nối bảng để ngỏ câu hỏi: danh mục Điện tử không có sản phẩm trực tiếp, vậy nó có bao nhiêu sản phẩm tính cả các danh mục con?\n\n```sql\nWITH RECURSIVE electronics AS (\n    SELECT id FROM categories WHERE id = 1\n    UNION ALL\n    SELECT c.id FROM categories c JOIN electronics e ON c.parent_id = e.id\n)\nSELECT p.name, p.category_id, p.price\nFROM products p\nWHERE p.category_id IN (SELECT id FROM electronics)\nORDER BY p.price DESC;\n```\n\nKết quả có 11 sản phẩm nằm ở Điện thoại, Laptop, Máy tính bảng và Phụ kiện.\n\n## Kiểu dữ liệu của cột đệ quy\n\n`name::text` ở phần gốc là cần thiết: cột của phần đệ quy phải cùng kiểu với phần gốc. Nối chuỗi làm kiểu thay đổi, nên ép về `text` ngay từ đầu.\n\n## Thử ngay\n\nÔ dưới đếm số sản phẩm trong cả nhánh Thời trang (id 7). Thử đổi sang Sách (id 10).', 3, 16, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000009'), 'so-do-to-chuc', 'Sơ đồ tổ chức nhiều cấp', '## Cấp bậc của từng nhân viên\n\n```sql\nWITH RECURSIVE org AS (\n    SELECT id, name, manager_id, 1 AS level, name::text AS chain\n    FROM employees\n    WHERE manager_id IS NULL\n    UNION ALL\n    SELECT e.id, e.name, e.manager_id, o.level + 1, o.chain || '' > '' || e.name\n    FROM employees e\n    JOIN org o ON e.manager_id = o.id\n)\nSELECT level, name, chain\nFROM org\nORDER BY chain;\n```\n\nCông ty có 4 cấp: giám đốc ở cấp 1, ba trưởng bộ phận ở cấp 2, sáu người ở cấp 3 và ba người ở cấp 4.\n\n## Từ dưới lên: chuỗi quản lý của một người\n\nĐổi chiều đệ quy để đi từ một nhân viên lên tới giám đốc:\n\n```sql\nWITH RECURSIVE chain AS (\n    SELECT id, name, manager_id, 0 AS steps_up\n    FROM employees\n    WHERE name = ''Quách Duy''\n    UNION ALL\n    SELECT m.id, m.name, m.manager_id, c.steps_up + 1\n    FROM employees m\n    JOIN chain c ON m.id = c.manager_id\n)\nSELECT steps_up, name FROM chain ORDER BY steps_up;\n```\n\n## Mọi cấp dưới của một quản lý\n\n```sql\nWITH RECURSIVE team AS (\n    SELECT id, name FROM employees WHERE name = ''Phạm Hùng''\n    UNION ALL\n    SELECT e.id, e.name FROM employees e JOIN team t ON e.manager_id = t.id\n)\nSELECT name FROM team WHERE name <> ''Phạm Hùng'';\n```\n\n## Dữ liệu vòng lặp\n\nNếu dữ liệu lỗi, ví dụ A quản lý B và B lại quản lý A, đệ quy sẽ không bao giờ dừng. Phòng thủ bằng cách giới hạn độ sâu (`WHERE level < 20`) trong phần đệ quy.\n\n## Thử ngay\n\nÔ dưới đếm số nhân viên ở mỗi cấp. Thử tính tổng quỹ lương của cả nhóm do Lê Thu phụ trách.', 4, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e005-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-500000000010'), 'on-tap-cte', 'Ôn tập: báo cáo nhiều bước với CTE', '## Bài toán tổng hợp\n\n> Với mỗi danh mục gốc (Điện tử, Thời trang, Sách), tính doanh thu đã giao tính cả danh mục con, và tỉ trọng trên tổng doanh thu.\n\n## Lời giải\n\n```sql\nWITH RECURSIVE tree AS (\n    SELECT id, id AS root_id\n    FROM categories\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT c.id, t.root_id\n    FROM categories c\n    JOIN tree t ON c.parent_id = t.id\n),\ndelivered AS (\n    SELECT p.category_id, oi.quantity * oi.unit_price AS amount\n    FROM order_items oi\n    JOIN orders o ON o.id = oi.order_id\n    JOIN products p ON p.id = oi.product_id\n    WHERE o.status = ''DELIVERED''\n),\nroot_revenue AS (\n    SELECT t.root_id, SUM(d.amount) AS revenue\n    FROM delivered d\n    JOIN tree t ON t.id = d.category_id\n    GROUP BY t.root_id\n)\nSELECT c.name AS root_category, r.revenue,\n       ROUND(100.0 * r.revenue / (SELECT SUM(revenue) FROM root_revenue), 1) AS percent\nFROM root_revenue r\nJOIN categories c ON c.id = r.root_id\nORDER BY r.revenue DESC;\n```\n\n## Đọc lại từng bước\n\n1. `tree`: gắn mỗi danh mục với danh mục gốc của nó.\n2. `delivered`: tiền của từng dòng hàng đã giao kèm danh mục sản phẩm.\n3. `root_revenue`: cộng tiền theo danh mục gốc.\n4. Truy vấn chính: thêm tên và tỉ trọng.\n\nĐể ý: thẻ quà tặng không có danh mục nên không thuộc nhánh nào.\n\n## Tự luyện\n\n1. Số nhân viên và quỹ lương của từng nhánh dưới giám đốc (mỗi trưởng bộ phận một nhánh).\n2. Dãy 7 ngày cuối tháng 12/2025 kèm số đơn mỗi ngày, ngày không có đơn hiện 0.\n\nChặng cuối, **SQL 6: Window function**, giúp tính xếp hạng, so với dòng trước và cộng dồn mà không cần gom nhóm.', 5, 15, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lesson_cells (id, lesson_id, cell_key, position, starter_sql, dialect, dataset_version_id, dataset_variant_id, dataset_checksum, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000001'), 1, 'WITH order_totals AS (\n    SELECT order_id, SUM(quantity * unit_price) AS order_total\n    FROM order_items\n    GROUP BY order_id\n)\nSELECT o.id, c.name, o.status, t.order_total\nFROM order_totals t\nJOIN orders o ON o.id = t.order_id\nJOIN customers c ON c.id = o.customer_id\nORDER BY t.order_total DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000002'), 1, 'WITH customer_spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spent\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.customer_id\n)\nSELECT customer_id, spent\nFROM customer_spend\nWHERE spent > (SELECT AVG(spent) FROM customer_spend)\nORDER BY spent DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000003'), 1, 'WITH paid_orders AS (\n    SELECT id, customer_id\n    FROM orders\n    WHERE status = ''DELIVERED''\n),\norders_per_customer AS (\n    SELECT customer_id, COUNT(*) AS paid_count\n    FROM paid_orders\n    GROUP BY customer_id\n)\nSELECT * FROM orders_per_customer\nORDER BY paid_count DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000004'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000004'), 1, 'WITH customer_spend AS (\n    SELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS spent\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY o.customer_id\n),\nsegmented AS (\n    SELECT customer_id, spent,\n           CASE\n               WHEN spent >= 30000000 THEN ''VIP''\n               WHEN spent >= 5000000 THEN ''Thân thiết''\n               ELSE ''Thường''\n           END AS segment\n    FROM customer_spend\n)\nSELECT segment, COUNT(*) AS customers, SUM(spent) AS total_spent\nFROM segmented\nGROUP BY segment\nORDER BY total_spent DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000005'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000005'), 1, 'WITH category_stats AS (\n    SELECT category_id, ROUND(AVG(price)) AS avg_price\n    FROM products\n    GROUP BY category_id\n)\nSELECT p.name, p.category_id, p.price, s.avg_price,\n       p.price - s.avg_price AS diff\nFROM products p\nJOIN category_stats s ON s.category_id = p.category_id\nORDER BY p.category_id, diff DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000006'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000006'), 1, 'WITH RECURSIVE numbers(n) AS (\n    SELECT 1\n    UNION ALL\n    SELECT n + 1 FROM numbers WHERE n < 10\n)\nSELECT n, n * n AS square FROM numbers;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000007'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000007'), 1, 'WITH RECURSIVE months(month) AS (\n    SELECT DATE ''2025-01-01''\n    UNION ALL\n    SELECT (month + INTERVAL ''1 month'')::date FROM months WHERE month < DATE ''2025-12-01''\n),\nmonthly_revenue AS (\n    SELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.id\n    WHERE o.status = ''DELIVERED''\n    GROUP BY 1\n)\nSELECT m.month, COALESCE(r.revenue, 0) AS revenue\nFROM months m\nLEFT JOIN monthly_revenue r ON r.month = m.month\nORDER BY m.month;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000008'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000008'), 1, 'WITH RECURSIVE tree AS (\n    SELECT id, name, parent_id, 1 AS depth, name::text AS path\n    FROM categories\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT c.id, c.name, c.parent_id, t.depth + 1, t.path || '' > '' || c.name\n    FROM categories c\n    JOIN tree t ON c.parent_id = t.id\n)\nSELECT path, depth\nFROM tree\nORDER BY path;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000009'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000009'), 2, 'WITH RECURSIVE branch AS (\n    SELECT id FROM categories WHERE id = 7\n    UNION ALL\n    SELECT c.id FROM categories c JOIN branch b ON c.parent_id = b.id\n)\nSELECT COUNT(*) AS products\nFROM products\nWHERE category_id IN (SELECT id FROM branch);', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000010'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000010'), 1, 'WITH RECURSIVE org AS (\n    SELECT id, name, manager_id, 1 AS level\n    FROM employees\n    WHERE manager_id IS NULL\n    UNION ALL\n    SELECT e.id, e.name, e.manager_id, o.level + 1\n    FROM employees e\n    JOIN org o ON e.manager_id = o.id\n    WHERE o.level < 20\n)\nSELECT level, COUNT(*) AS employees, STRING_AGG(name, '', '') AS names\nFROM org\nGROUP BY level\nORDER BY level;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000011'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000011'), 2, 'WITH RECURSIVE chain AS (\n    SELECT id, name, manager_id, 0 AS steps_up\n    FROM employees\n    WHERE name = ''Quách Duy''\n    UNION ALL\n    SELECT m.id, m.name, m.manager_id, c.steps_up + 1\n    FROM employees m\n    JOIN chain c ON m.id = c.manager_id\n)\nSELECT steps_up, name FROM chain ORDER BY steps_up;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-600000000012'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e005-0000-7000-8000-700000000012'), 1, 'WITH RECURSIVE tree AS (\n    SELECT id, id AS root_id\n    FROM categories\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT c.id, t.root_id\n    FROM categories c\n    JOIN tree t ON c.parent_id = t.id\n),\ndelivered AS (\n    SELECT p.category_id, oi.quantity * oi.unit_price AS amount\n    FROM order_items oi\n    JOIN orders o ON o.id = oi.order_id\n    JOIN products p ON p.id = oi.product_id\n    WHERE o.status = ''DELIVERED''\n),\nroot_revenue AS (\n    SELECT t.root_id, SUM(d.amount) AS revenue\n    FROM delivered d\n    JOIN tree t ON t.id = d.category_id\n    GROUP BY t.root_id\n)\nSELECT c.name AS root_category, r.revenue,\n       ROUND(100.0 * r.revenue / (SELECT SUM(revenue) FROM root_revenue), 1) AS percent\nFROM root_revenue r\nJOIN categories c ON c.id = r.root_id\nORDER BY r.revenue DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO quiz_questions (id, lesson_id, question_key, prompt, is_multiple, position, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e005-0000-7000-8000-800000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-900000000001'), 'CTE tồn tại trong bao lâu?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-800000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e005-0000-7000-8000-900000000002'), 'Lợi ích chính của CTE so với subquery lồng trong FROM là gì?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-800000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-900000000003'), 'Viết nhiều CTE trong một câu lệnh thế nào?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-800000000004'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e005-0000-7000-8000-900000000004'), 'CTE thứ hai có dùng được kết quả của CTE thứ nhất không?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e005-0000-7000-8000-800000000005'), UUID_TO_BIN('01a1e005-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e005-0000-7000-8000-900000000005'), 'Việc nào chỉ CTE làm được, subquery thường thì không?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
